STORIES={}
for line in ROWS.splitlines():
    code,*values=line.split("|")
    if len(values)!=len(KEYS) or not all(values):
        raise ValueError("Incomplete landing localization for "+code)
    STORIES[code]=dict(zip(KEYS,values))

def story(key: str) -> str:
    code=locale()
    if code not in STORIES or key not in STORIES[code]:
        raise KeyError(f"Missing localized journey copy: {code}/{key}")
    return STORIES[code][key]

def story_html(key: str) -> str:
    return escape(story(key))

